insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('aaaa0006-0000-4000-8000-000000000003', 'en', null, 'German B1 — Confident conversations', 'A CEFR B1 German course (Deutsch) that turns solid basics into confident everyday conversation: narrate the past with the Präteritum, make polite requests and hypotheticals with the Konjunktiv II, handle work, health and travel situations, and give and defend your opinions. Aligned to CEFR B1; structure adapted from open German curricula on OER Commons (CC BY 4.0).', 'B1', 'fluency', 12, true, 'language', '{aaaa0006-0000-4000-8000-000000000002}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'aaaa0006-0000-4000-8000-000000000003', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Where you stand: a B1 self-check', 'reading', '{"sections":[{"heading":"What B1 sounds like","text":"At B1 you stop translating word by word and start telling stories. You can already order food, describe your routine and talk about the past with the Perfekt. Now you will connect ideas, react to what other people say, and hold your own in a real conversation. Read this short self-portrait of a B1 speaker: ''Ich lerne seit zwei Jahren Deutsch. Ich kann über meine Arbeit und meine Pläne sprechen und verstehe die meisten Gespräche im Alltag. Manchmal fehlen mir Wörter, aber ich kann sie umschreiben.''"},{"heading":"Quick warm-up: review from A2","text":"Before the new material, reactivate what you know. The Perfekt uses a helper (haben or sein) plus a participle at the end: Ich habe gestern lange gearbeitet. Ich bin am Wochenende nach München gefahren. Modal verbs send the second verb to the end: Ich möchte dieses Jahr mehr reisen. Subordinate clauses with weil, dass and wenn push the conjugated verb to the very end: Ich lerne Deutsch, weil ich in Österreich arbeiten möchte."},{"heading":"What is coming in this course","text":"In the next lessons you will build vocabulary for work, health and travel, learn the written narrative past (Präteritum), master the polite and hypothetical Konjunktiv II, and practise two full conversations: a visit to the doctor and a job interview. You will read a longer B1 text and finish with a checkpoint quiz. The goal is confidence, not perfection — being understood matters more than being flawless."},{"heading":"Your turn","text":"Write four or five sentences that answer three questions in German: Wie lange lernst du schon Deutsch? Warum lernst du Deutsch? Was möchtest du auf Deutsch machen können? Try to use one weil-clause and one modal verb. Keep this text; at the end of the course you can rewrite it and see how much more natural it sounds."}]}'::jsonb, null, 10),
  (2, 'Work & career', 'vocab', '{"items":[{"term":"die Stelle","translation":"the position / job","ipa":"diː ˈʃtɛlə","example":"Ich habe mich um eine neue Stelle beworben."},{"term":"sich bewerben","translation":"to apply (for a job)","ipa":"zɪç bəˈvɛʁbn̩","example":"Sie bewirbt sich bei einer großen Firma in Hamburg."},{"term":"der Lebenslauf","translation":"the CV / résumé","ipa":"deːɐ̯ ˈleːbn̩sˌlaʊf","example":"Bitte schicken Sie uns Ihren Lebenslauf per E-Mail."},{"term":"die Kollegin","translation":"the (female) colleague","ipa":"diː kɔˈleːɡɪn","example":"Meine Kollegin hilft mir oft bei schwierigen Aufgaben."},{"term":"die Besprechung","translation":"the meeting","ipa":"diː bəˈʃpʁɛçʊŋ","example":"Um zehn Uhr haben wir eine wichtige Besprechung."},{"term":"der Termin","translation":"the appointment / deadline","ipa":"deːɐ̯ tɛʁˈmiːn","example":"Können wir einen Termin für nächste Woche vereinbaren?"},{"term":"die Erfahrung","translation":"the experience","ipa":"diː ɛɐ̯ˈfaːʁʊŋ","example":"Ich habe viel Erfahrung im Kundenservice."},{"term":"die Gehaltserhöhung","translation":"the pay rise","ipa":"diː ɡəˈhaltsʔɛɐ̯ˌhøːʊŋ","example":"Nach einem Jahr habe ich um eine Gehaltserhöhung gebeten."},{"term":"die Überstunden","translation":"the overtime","ipa":"diː ˈyːbɐˌʃtʊndn̩","example":"Diese Woche musste ich viele Überstunden machen."},{"term":"kündigen","translation":"to quit / give notice","ipa":"ˈkʏndɪɡn̩","example":"Er hat gekündigt, weil er ein besseres Angebot bekommen hat."},{"term":"der Arbeitgeber","translation":"the employer","ipa":"deːɐ̯ ˈaʁbaɪtsˌɡeːbɐ","example":"Mein Arbeitgeber bietet flexible Arbeitszeiten an."}]}'::jsonb, 'Job titles often have a feminine form ending in -in: der Kollege → die Kollegin, der Chef → die Chefin. When you say your profession you drop the article: Ich bin Ingenieurin (not eine Ingenieurin).', 10),
  (3, 'Health & the body', 'vocab', '{"items":[{"term":"die Gesundheit","translation":"the health","ipa":"diː ɡəˈzʊnthaɪt","example":"Gesundheit ist wichtiger als Geld."},{"term":"sich fühlen","translation":"to feel","ipa":"zɪç ˈfyːlən","example":"Ich fühle mich heute nicht so gut."},{"term":"die Erkältung","translation":"the cold (illness)","ipa":"diː ɛɐ̯ˈkɛltʊŋ","example":"Ich habe eine Erkältung und bleibe zu Hause."},{"term":"das Fieber","translation":"the fever","ipa":"das ˈfiːbɐ","example":"Das Kind hat hohes Fieber und muss ins Bett."},{"term":"die Schmerzen","translation":"the pain(s)","ipa":"diː ˈʃmɛʁtsn̩","example":"Ich habe seit gestern starke Schmerzen im Rücken."},{"term":"der Arzt / die Ärztin","translation":"the doctor","ipa":"deːɐ̯ aːʁtst diː ˈɛːʁtstɪn","example":"Du solltest wirklich zum Arzt gehen."},{"term":"die Apotheke","translation":"the pharmacy","ipa":"diː apoˈteːkə","example":"In der Apotheke bekommst du etwas gegen Husten."},{"term":"das Rezept","translation":"the prescription","ipa":"das ʁeˈtsɛpt","example":"Die Ärztin hat mir ein Rezept für Antibiotika gegeben."},{"term":"sich ausruhen","translation":"to rest","ipa":"zɪç ˈaʊsˌʁuːən","example":"Du musst dich ein paar Tage ausruhen."},{"term":"gesund werden","translation":"to get well","ipa":"ɡəˈzʊnt ˈveːɐ̯dn̩","example":"Ich hoffe, du wirst bald wieder gesund."}]}'::jsonb, 'To say what hurts, German uses tun weh (to hurt) with the dative: Mir tut der Kopf weh, Mir tun die Füße weh. Literally ''the head hurts to me''. The person in pain is in the dative (mir, dir, ihm).', 10),
  (4, 'The Präteritum: the narrative past', 'grammar', '{"sections":[{"heading":"When to use the Präteritum","text":"In speech Germans prefer the Perfekt (Ich habe gearbeitet), but in writing — stories, reports, newspapers — and with a handful of very common verbs even in speech, they use the Präteritum, the simple past. It is one word, not two: arbeiten → ich arbeitete, gehen → ich ging. You already know two of them: war (was) and hatte (had)."},{"heading":"Regular (weak) verbs","text":"Weak verbs add -te to the stem, then the personal ending: machen → ich machte, du machtest, er machte, wir machten, sie machten. So Ich machte meine Hausaufgaben means ''I did my homework''. Verbs whose stem ends in -t or -d add an extra e: arbeiten → arbeitete, warten → wartete: Wir warteten eine Stunde auf den Bus."},{"heading":"Irregular (strong) verbs","text":"Strong verbs change their stem vowel and take no -te: gehen → ging, kommen → kam, sehen → sah, fahren → fuhr, geben → gab, finden → fand, sprechen → sprach. The ich and er forms have no ending: ich ging, er ging. Example: Sie kam spät nach Hause und ging sofort ins Bett. A short list covers most stories, so it is worth learning the common ones by heart."},{"heading":"The everyday six","text":"Even in conversation, these are almost always used in the Präteritum rather than the Perfekt: sein → war, haben → hatte, and the modal verbs können → konnte, müssen → musste, wollen → wollte, dürfen → durfte. So you say Ich war müde, Ich hatte keine Zeit, Ich konnte nicht kommen, Wir mussten früh aufstehen. Using these correctly instantly makes your German sound more natural."}]}'::jsonb, null, 13),
  (5, 'Konjunktiv II: polite requests & hypotheticals', 'grammar', '{"sections":[{"heading":"Why you need it","text":"The Konjunktiv II is the ''would'' form. It does two everyday jobs: it makes requests and wishes polite, and it talks about unreal or hypothetical situations. Compare the blunt Ich will ein Bier with the polite Ich hätte gern ein Bier (''I would like a beer''). At B1, sounding polite is as important as being correct."},{"heading":"The easy way: würde + infinitive","text":"For almost every verb you can build the Konjunktiv II with würde plus the infinitive at the end, just like English ''would'': Ich würde dir helfen (I would help you), An deiner Stelle würde ich das nicht machen (In your place I wouldn''t do that), Wir würden gern kommen. This one pattern gets you through most situations."},{"heading":"The short forms you must know","text":"A few very common verbs sound clumsy with würde, so they keep their own short forms: sein → wäre (Das wäre toll — that would be great), haben → hätte (Ich hätte eine Frage — I''d have a question), and the modals können → könnte (Könntest du mir helfen? — could you help me?), müssen → müsste, dürfen → dürfte, mögen → möchte. Note the umlaut: hatte (had, real past) versus hätte (would have, hypothetical)."},{"heading":"Polite requests and unreal wishes","text":"Use it to ask for things gently: Könnten Sie das bitte wiederholen? Würden Sie mir einen Gefallen tun? Dürfte ich Sie etwas fragen? Use it for wishes and hypotheticals, often with wenn: Wenn ich mehr Zeit hätte, würde ich mehr reisen (If I had more time, I would travel more). Ich wünschte, ich könnte besser Deutsch. This is the polite, diplomatic register that marks a confident B1 speaker."}]}'::jsonb, 'The safe, everyday Konjunktiv II is würde + infinitive: Ich würde gern mitkommen. For sein, haben and the modals, use the short forms wäre, hätte, könnte, müsste instead.', 14),
  (6, 'Travel & transport', 'vocab', '{"items":[{"term":"die Reise","translation":"the trip / journey","ipa":"diː ˈʁaɪzə","example":"Wir planen eine Reise durch Österreich."},{"term":"verreisen","translation":"to travel / go away","ipa":"fɛɐ̯ˈʁaɪzn̩","example":"Im Sommer verreisen wir meistens ans Meer."},{"term":"der Bahnhof","translation":"the train station","ipa":"deːɐ̯ ˈbaːnˌhoːf","example":"Der Zug fährt in zehn Minuten vom Bahnhof ab."},{"term":"umsteigen","translation":"to change (trains) / transfer","ipa":"ˈʊmˌʃtaɪɡn̩","example":"In Frankfurt müssen Sie in den ICE umsteigen."},{"term":"die Verspätung","translation":"the delay","ipa":"diː fɛɐ̯ˈʃpɛːtʊŋ","example":"Der Zug hat leider zwanzig Minuten Verspätung."},{"term":"die Fahrkarte","translation":"the ticket","ipa":"diː ˈfaːɐ̯ˌkaʁtə","example":"Ich habe eine Fahrkarte für den nächsten Zug gekauft."},{"term":"die Unterkunft","translation":"the accommodation","ipa":"diː ˈʊntɐˌkʊnft","example":"Wir suchen noch eine günstige Unterkunft für zwei Nächte."},{"term":"buchen","translation":"to book","ipa":"ˈbuːxn̩","example":"Ich habe das Hotel schon online gebucht."},{"term":"das Gepäck","translation":"the luggage","ipa":"das ɡəˈpɛk","example":"Mein Gepäck ist zu schwer für das Flugzeug."},{"term":"sich verlaufen","translation":"to get lost (on foot)","ipa":"zɪç fɛɐ̯ˈlaʊfn̩","example":"In der Altstadt haben wir uns leider verlaufen."},{"term":"die Sehenswürdigkeit","translation":"the sight / landmark","ipa":"diː ˈzeːənsˌvʏʁdɪçkaɪt","example":"Der Kölner Dom ist eine berühmte Sehenswürdigkeit."}]}'::jsonb, 'With means of transport use mit + dative: mit dem Zug, mit dem Bus, mit der Bahn, mit dem Auto. The one exception is on foot: zu Fuß. Destinations with cities take nach: nach Berlin fahren.', 10),
  (7, 'At the doctor''s', 'roleplay', '{"scenario":"You are at a doctor''s practice (die Arztpraxis) in Vienna because you have not felt well for several days. Greet the doctor, describe your symptoms (for example Kopfschmerzen, Fieber, Halsschmerzen), say since when you have had them (seit drei Tagen), answer questions about your sleep and appetite, and understand the doctor''s advice and prescription. Use phrases like Mir tut der Hals weh, Ich fühle mich schlapp and Seit wann haben Sie das?","persona":"A calm, thorough doctor who addresses you with Sie, asks follow-up questions about your symptoms, gives clear advice (sich ausruhen, viel trinken) and explains a prescription","goal":"Describe your symptoms clearly, answer the doctor''s questions, and correctly understand the advice, the prescription and when to come back — all in German"}'::jsonb, null, 11),
  (8, 'A job interview', 'roleplay', '{"scenario":"You have a job interview (das Vorstellungsgespräch) at a company in Berlin. Introduce yourself, talk about your experience and strengths, explain why you want this position and why you left your last job, ask two questions about the role or the team, and discuss when you could start. Use the polite Konjunktiv II where it helps: Ich würde gern in Ihrem Team arbeiten, Könnten Sie mir mehr über die Aufgaben sagen?","persona":"A friendly but professional interviewer who uses Sie, asks about your strengths, weaknesses and motivation, and expects concrete examples rather than vague answers","goal":"Present yourself convincingly, back up your strengths with an example, ask thoughtful questions, and agree on the next step in the process, entirely in German"}'::jsonb, null, 12),
  (9, 'Reading: a change of plans', 'reading', '{"sections":[{"heading":"The text","text":"Read Tarek''s email to his friend: ''Hallo Jonas, eigentlich wollte ich dir schon früher schreiben, aber die letzten Wochen waren verrückt. Ich habe nämlich meinen Job gewechselt! Bei meiner alten Firma musste ich fast jeden Tag Überstunden machen und war ständig müde. Als ich die neue Stelle sah, bewarb ich mich sofort. Das Vorstellungsgespräch lief gut, und seit Montag arbeite ich jetzt in einem kleineren Team. Wenn ich mehr Zeit hätte, würde ich dich gern bald besuchen. Melde dich, wenn du am Wochenende frei bist! Viele Grüße, Tarek.''"},{"heading":"Past forms in the text","text":"Notice the mix of past tenses. In the Perfekt: Ich habe meinen Job gewechselt. In the Präteritum, typical of narration: die Wochen waren verrückt, ich musste Überstunden machen, ich war müde, ich sah die Stelle, ich bewarb mich, das Gespräch lief gut. In speech Germans switch easily between the two; here the strong verbs sah, bewarb and lief carry the story forward."},{"heading":"The Konjunktiv II","text":"Tarek also uses the hypothetical form: Wenn ich mehr Zeit hätte, würde ich dich gern besuchen (''If I had more time, I would like to visit you''). The wenn-clause uses hätte and the main clause uses würde + infinitive — exactly the polite, unreal pattern from the grammar lesson. It signals that the visit is a wish, not a firm plan."},{"heading":"Comprehension","text":"Answer in German: Warum hat Tarek seinen Job gewechselt? (Was er über seine alte Firma? Warum war er müde?) Wie lief das Vorstellungsgespräch, und seit wann hat er die neue Stelle? Was möchte Tarek machen, wenn er mehr Zeit hätte? Then write a short reply from Jonas: react to the news, ask one question about the new job, and suggest a time to meet. Use at least one weil-clause and one Konjunktiv II form."}]}'::jsonb, null, 12),
  (10, 'B1 checkpoint', 'quiz', '{"questions":[{"prompt":"Choose the correct Präteritum: ''She came home late.'' Sie ___ spät nach Hause.","options":["kommte","kam","gekommen","kommen"],"answer":1,"explanation":"kommen is a strong verb, so the Präteritum is kam (no -te ending, changed vowel): Sie kam spät nach Hause. ''kommte'' does not exist, and ''gekommen'' is the participle used in the Perfekt."},{"prompt":"Which sentence uses the everyday Präteritum of a modal verb correctly?","options":["Ich musste gestern lange arbeiten.","Ich habe gestern lange arbeiten gemusst.","Ich muss gestern lange arbeiten.","Ich wollte gestern lange arbeiten gehabt."],"answer":0,"explanation":"Modal verbs are normally used in the Präteritum even in speech: musste, konnte, wollte, durfte. Ich musste gestern lange arbeiten is the natural form; the Perfekt of modals is rare and clumsy."},{"prompt":"Make this polite with Konjunktiv II: ''Can you help me?'' ___ Sie mir bitte helfen?","options":["Können","Konnten","Könnten","Kannten"],"answer":2,"explanation":"The polite Konjunktiv II of können is könnten (with an umlaut): Könnten Sie mir bitte helfen? ''Können'' is a plain request, ''konnten'' is the real past (''could / were able to''), and ''kannten'' is from kennen."},{"prompt":"Complete the hypothetical: ''If I had more time, I would travel more.'' Wenn ich mehr Zeit ___, würde ich mehr reisen.","options":["habe","hatte","hätte","haben"],"answer":2,"explanation":"An unreal wenn-clause needs the Konjunktiv II hätte (with umlaut), paired with würde in the main clause: Wenn ich mehr Zeit hätte, würde ich mehr reisen. ''hatte'' without the umlaut is the real past (''had'')."},{"prompt":"How do you say ''My head hurts''?","options":["Ich habe Kopf weh.","Mir tut der Kopf weh.","Ich bin Kopfschmerzen.","Der Kopf tut mich weh."],"answer":1,"explanation":"German uses tun ... weh with the person in the dative: Mir tut der Kopf weh (literally ''the head hurts to me''). The dative is mir, not the accusative mich, so ''tut mich weh'' is wrong."},{"prompt":"Which preposition and case are correct? ''I travel by train.'' Ich fahre ___ Zug.","options":["mit dem","mit den","mit der","in den"],"answer":0,"explanation":"Means of transport use mit + dative, and der Zug is masculine, so der becomes dem: mit dem Zug. ''mit den'' is dative plural and ''mit der'' would be feminine."},{"prompt":"You want to apply for a job. Which sentence is correct?","options":["Ich bewerbe mich um eine neue Stelle.","Ich bewerbe eine neue Stelle.","Ich bewerbe mich eine neue Stelle an.","Ich mich bewerbe um eine neue Stelle."],"answer":0,"explanation":"sich bewerben is reflexive and takes the preposition um: Ich bewerbe mich um eine neue Stelle. The reflexive pronoun mich is required, and the finite verb bewerbe stays in second position."},{"prompt":"Which sentence correctly reports the past in a narrative (Präteritum)?","options":["Als ich die Stelle sehe, bewerbe ich mich.","Als ich die Stelle sah, bewarb ich mich.","Als ich die Stelle gesehen, bewarb ich mich.","Als ich die Stelle sah, bewerbte ich mich."],"answer":1,"explanation":"Both verbs are strong and take the Präteritum with a vowel change: sehen → sah, sich bewerben → bewarb. Als ich die Stelle sah, bewarb ich mich. ''bewerbte'' is not a valid form."}]}'::jsonb, null, 9)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'aaaa0006-0000-4000-8000-000000000003' and l.position = v.pos
);
